  const rd2=Math.tanh((act2-inh2*0.6+bg*0.2+radial+spiral2)*1.8);
  const cross=Math.tanh((rd1*0.6+rd2*0.4+cell*0.3)*2.0);
  const bal=(act-inh)*0.08;
  const edge=Math.abs(cross)>0.6?1.2:Math.abs(cross)>0.3?1.05:1.0;
  const lum=0.85+Math.sin(cross*Math.PI*1.5)*0.15+Math.sin(t*0.3)*0.05;
